    const saved = current || legacy;
    if (!validChartPreferences(saved)) return defaultChartPreferences();
    const savedPreferences = { ...saved }; delete savedPreferences.theme;
    const state = { ...defaultChartPreferences(), ...savedPreferences, version:2, indicators:saved.indicators.map((indicator)=>({ ...indicator, settings:{ ...MarketChart.defaults[indicator.type], ...indicator.settings } })), comparisons:Array.isArray(saved.comparisons) ? saved.comparisons.slice(0,3) : [] };
