function bindToolPanels(){ document.querySelectorAll(".chart-toolbar details").forEach((panel)=>{ if(panel.dataset.bound) return; panel.dataset.bound="1"; panel.addEventListener("toggle",()=>{ if(!panel.open) return; document.querySelectorAll(".chart-toolbar details[open]").forEach((other)=>{ if(other!==panel) other.open=false; }); }); }); }
function bindDetailChartControls(symbol,state,config) {
  document.querySelectorAll(".chart-menu [data-range]").forEach((button)=>button.onclick=()=>{ state.range=button.dataset.range; state.interval=chartIntervalDefaults[state.range]; saveChartPreferences(state); renderDetail(symbol); });
  document.querySelector("[data-chart-interval]").onchange=(event)=>{ state.interval=event.target.value; saveChartPreferences(state); renderDetail(symbol); };
  document.querySelector("[data-chart-type]").onchange=(event)=>{ state.type=event.target.value; config.type=state.type; saveChartPreferences(state); rerenderChart(config); };
  document.querySelector("[data-add-indicator]").onclick=()=>{ const type=document.querySelector("[data-indicator-add]").value; state.indicators.push(MarketChart.createIndicator(type,crypto.randomUUID())); config.indicators=state.indicators; saveChartPreferences(state); rerenderChart(config); refreshIndicatorControls(state,config); };
  document.querySelector("[data-extended-hours]").onchange=(event)=>{ state.extendedHours=event.target.checked; saveChartPreferences(state); renderDetail(symbol); };
  document.querySelector("[data-log-scale]").onchange=(event)=>{ state.logScale=event.target.checked; config.logScale=state.logScale; saveChartPreferences(state); rerenderChart(config); };
  const addComparison=document.querySelector("[data-add-comparison]"); addComparison.onclick=async()=>{ const input=document.querySelector("[data-comparison-symbol]"), error=document.querySelector("[data-comparison-error]"), candidate=input.value.trim().toUpperCase(); error.textContent=""; if(!/^[A-Z0-9.^=-]{1,24}$/.test(candidate)||candidate===symbol||state.comparisons.includes(candidate)){ error.textContent="Enter a different valid ticker."; return; } if(state.comparisons.length>=3){ error.textContent="A maximum of three comparisons is supported."; return; } try { addComparison.disabled=true; addComparison.textContent="Adding…"; const quote=await loadComparison(candidate,state); state.comparisons.push(candidate); state.logScale=false; config.logScale=false; config.comparisonData.push({symbol:candidate,points:quote.points}); saveChartPreferences(state); renderComparisonControls(state); document.querySelector("[data-log-scale]").checked=false; document.querySelector("[data-log-scale]").disabled=true; input.value=""; rerenderChart(config); bindDetailChartControls(symbol,state,config); } catch(fetchError){ error.textContent=fetchError.message; addComparison.disabled=false; } finally { addComparison.textContent="Add"; } };
  document.querySelector("[data-comparison-symbol]").onkeydown=(event)=>{ if(event.key==="Enter"){ event.preventDefault(); addComparison.click(); } };
  document.querySelectorAll("[data-remove-comparison]").forEach((button)=>button.onclick=()=>{ state.comparisons=state.comparisons.filter((item)=>item!==button.dataset.removeComparison); config.comparisonData=config.comparisonData.filter((item)=>item.symbol!==button.dataset.removeComparison); saveChartPreferences(state); renderComparisonControls(state); const log=document.querySelector("[data-log-scale]"); log.disabled=state.comparisons.length>0; rerenderChart(config); bindDetailChartControls(symbol,state,config); });
  document.querySelector("[data-save-layout]").onclick=()=>{ const input=document.querySelector("[data-layout-name]"), name=input.value.trim(); if(!name) return input.focus(); const layouts=loadLayouts(); layouts[name]=JSON.parse(JSON.stringify(state)); saveLayouts(layouts); input.value=""; document.querySelector("[data-layout-select]").innerHTML=`<option value="">Choose layout</option>${layoutOptions()}`; };
  document.querySelector("[data-load-layout]").onclick=()=>{ const name=document.querySelector("[data-layout-select]").value, layout=loadLayouts()[name]; if(!validChartPreferences(layout)) return; saveChartPreferences({...defaultChartPreferences(),...layout,version:2}); renderDetail(symbol); };
  document.querySelector("[data-delete-layout]").onclick=()=>{ const select=document.querySelector("[data-layout-select]"), name=select.value; if(!name) return; const layouts=loadLayouts(); delete layouts[name]; saveLayouts(layouts); select.innerHTML=`<option value="">Choose layout</option>${layoutOptions()}`; };
  bindIndicatorControls(state,config); bindChartInteractions(app); bindToolPanels();
}
const fact=(label,value)=>value==null||value===""||value.includes?.("—")?"":`<div><dt>${label}</dt><dd>${value}</dd></div>`;
function quoteFacts(quote){ return [fact("Currency",escapeHtml(quote.currency||"")),fact("Market State",escapeHtml(quote.marketState||"")),Number.isFinite(quote.open)?fact("Open",money(quote.open,quote.currency)):"",Number.isFinite(quote.previousClose)?fact("Previous Close",money(quote.previousClose,quote.currency)):"",Number.isFinite(quote.dayLow)&&Number.isFinite(quote.dayHigh)?fact("Day Range",`${money(quote.dayLow,quote.currency)} – ${money(quote.dayHigh,quote.currency)}`):"",Number.isFinite(quote.fiftyTwoWeekLow)&&Number.isFinite(quote.fiftyTwoWeekHigh)?fact("52-Week Range",`${money(quote.fiftyTwoWeekLow,quote.currency)} – ${money(quote.fiftyTwoWeekHigh,quote.currency)}`):"",Number.isFinite(quote.volume)?fact("Volume",number(quote.volume)):"",fact("Exchange",escapeHtml(quote.exchange||"")),fact("Timezone",escapeHtml(quote.exchangeTimezone||"")),fact("Instrument",escapeHtml(quote.instrumentType||""))].join("")||`<p class="muted">Quote details are unavailable.</p>`; }
function positionPanel(holding,quote){ if(!holding) return `<p class="muted">${escapeHtml(quote.symbol)} is not in local holdings.</p>`; const value=Number.isFinite(quote.price)?quote.price*holding.quantity:null, profit=value!=null&&Number.isFinite(holding.purchasePrice)?(quote.price-holding.purchasePrice)*holding.quantity:null; return `<dl class="facts">${fact("Quantity",number(holding.quantity))}${Number.isFinite(holding.purchasePrice)?fact("Average Cost",money(holding.purchasePrice,holding.currency)):""}${value!=null?fact("Market Value",money(value,quote.currency||holding.currency)):""}${profit!=null?fact("Unrealized P/L",money(profit,quote.currency||holding.currency)):""}</dl>`; }
function analysisPanel(points,currency){ const result=MarketChart.technicalAnalysis(points); if(!result.available) return `<p class="muted">${escapeHtml(result.reason)}</p>`; return `<p class="analysis-note">Rule-based technical summary · ${result.confidence} data confidence</p><dl class="facts">${fact("Trend",escapeHtml(result.trend))}${fact("Momentum",escapeHtml(result.momentum))}${fact("RSI",`${result.rsi.toFixed(1)} · ${escapeHtml(result.rsiState)}`)}${fact("Support",money(result.support,currency))}${fact("Resistance",money(result.resistance,currency))}${fact("Period Volatility",`${result.volatility.toFixed(2)}%`)}</dl><p class="analysis-disclaimer">Analysis describes the loaded candles and is not a trading recommendation.</p>`; }
function detailRail(quote,holding){ return `<aside class="detail-card detail-rail" aria-label="Stock information"><div class="rail-head"><div class="rail-tabs" role="tablist" aria-label="Stock information tabs"><button role="tab" aria-selected="true" aria-controls="rail-quote" id="tab-quote">Quote</button><button role="tab" aria-selected="false" aria-controls="rail-position" id="tab-position" tabindex="-1">Position</button><button role="tab" aria-selected="false" aria-controls="rail-news" id="tab-news" tabindex="-1">News</button><button role="tab" aria-selected="false" aria-controls="rail-analysis" id="tab-analysis" tabindex="-1">Analysis V2</button></div><button class="rail-close" type="button" data-close-rail aria-label="Close details">×</button></div><section class="rail-panel" id="rail-quote" role="tabpanel" aria-labelledby="tab-quote"><dl class="facts">${quoteFacts(quote)}</dl></section><section class="rail-panel" id="rail-position" role="tabpanel" aria-labelledby="tab-position" hidden>${positionPanel(holding,quote)}</section><section class="rail-panel" id="rail-news" role="tabpanel" aria-labelledby="tab-news" hidden><p class="muted">Loading news…</p></section><section class="rail-panel" id="rail-analysis" role="tabpanel" aria-labelledby="tab-analysis" hidden>${analysisPanel(quote.points,quote.currency)}</section></aside>`; }
async function renderDetail(symbol) {
  const state=loadChartPreferences(); detailChartState=state; activeDetailSymbol=symbol;
  clearInterval(quoteTimer); stopDetailRefresh(); app.innerHTML=`<section class="page"><div class="status">Loading ${escapeHtml(symbol)}…</div></section>`;
  try {
    const [quote,holdings]=await Promise.all([api(chartQuery(symbol,state.range,state.interval,state.extendedHours)),api("/api/holdings")]);
    setHoldingSymbols(holdings);
    const comparisonResults=await Promise.allSettled(state.comparisons.map((candidate)=>loadComparison(candidate,state)));
    const comparisonData=comparisonResults.flatMap((result,index)=>result.status==="fulfilled"?[{symbol:state.comparisons[index],points:result.value.points}]:[]);
    const stale=isQuoteStale(quote), holding=holdings.find((item)=>item.symbol===quote.symbol);
    chartInstances.clear();
    app.innerHTML=`<section class="graph-workspace"><div class="detail-layout"><section class="detail-card chart-card"><div class="chart-card-head"><a href="#/" class="back" aria-label="Back to Dashboard">←</a><div class="instrument-title"><div class="eyebrow">${escapeHtml(quote.exchange||"Market Data")}</div><h1>${escapeHtml(quote.symbol)} <span class="muted">${escapeHtml(quote.name)}</span></h1><div class="status ${stale?"warning":""}">${ageLabel(quote)} · ${escapeHtml(quote.source)} · received ${new Date(quote.receivedAt).toLocaleTimeString()}</div></div><div class="detail-price">${money(quote.price,quote.currency)}<small class="${quoteClass(quote)}">${quote.changePercent==null?"Change unavailable":`${quote.change>=0?"+":""}${money(quote.change,quote.currency)} (${quote.changePercent.toFixed(2)}%)`}</small></div></div>${chartToolbar(state)}${chartSvg(quote.points,state,quote.currency,comparisonData)}</section>${detailRail(quote,holding)}</div></section>`;
    const shell=document.querySelector(".chart-shell"), config=chartInstances.get(shell.dataset.chartId); activeDetailChartId=shell?.dataset.chartId||null; bindDetailChartControls(symbol,state,config); bindRail(); loadNewsPanel(symbol);
  } catch(error) { app.innerHTML=`<section class="page"><a href="#/" class="back">← Back to Dashboard</a><div class="error" style="margin-top:22px"><b>${escapeHtml(symbol)}</b> could not be loaded. ${escapeHtml(error.message)}<br><small>Market data is temporarily unavailable.</small></div></section>`; }
}
function closeSearchResults() { document.querySelector("#search-results")?.setAttribute("hidden", ""); }
